            string cleaned = "";
            for (int i = 0; i < paragraph.Length; i++)
            {
                char c = paragraph[i];
                if (char.IsLetterOrDigit(c) || char.IsWhiteSpace(c)) 
                cleaned += c;
            } // removing punctuations.
            string[] words = cleaned.Split(' ', StringSplitOptions.RemoveEmptyEntries);
            int[] count = new int[words.Length];
            // counting the frequency 
            Stopwatch stopwatch = new Stopwatch();
            stopwatch.Start();
            for (int i = 0; i < words.Length; i++)
            {
                for (int j = 0; j < words.Length; j++)
                {
                    if (words[i] == words[j])
                    {
                        count[i]++;
                    }
                }


            }
            stopwatch.Stop();
            Console.WriteLine($"Time taken to count frequency using nested loops: {stopwatch.ElapsedMilliseconds} ms");
            stopwatch.Reset();
            stopwatch.Start();

            Dictionary<string, int> wordCount = new Dictionary<string, int>();

            for (int i = 0; i < words.Length; i++)
            {
                if (wordCount.ContainsKey(words[i]))
                {
                    wordCount[words[i]]++;
                }
                else
                {
                    wordCount[words[i]] = 1;
                }
            }
            stopwatch.Stop();
            Console.WriteLine($"Time taken to count frequency using dictionary: {stopwatch.ElapsedMilliseconds} ms");


            //printing result 
            Console.WriteLine("---------------------------------------------------------");
            Console.WriteLine($"{"Word",15} {"Count",15} {"Bar",20}");
            Console.WriteLine("---------------------------------------------------------");
